def moving_average_2dp(lst, k):
    n = len(lst)
    if k <= 0 or k > n:
        return []
    total = sum(lst[:k])
    result = [round(total / k, 2)]
    for i in range(k, n):
        total += lst[i] - lst[i - k]
        result.append(round(total / k, 2))
    return result

def kth_smallest_using_merge(a, b, k):
