def compress_ranges(lst):
    if not lst:
        return []
    from itertools import groupby
    groups = groupby(enumerate(lst), key=lambda p: p[1] - p[0])
    result = []
    for _, grp in groups:
        vals = [v for _, v in grp]
        result.append([vals[0], vals[-1]])
    return result

