def min_left_rotations_to_sort(lst):
    n = len(lst)
    if n <= 1:
        return 0
    descents = [i for i in range(n) if lst[i] > lst[(i + 1) % n]]
    if len(descents) == 0:
        return 0
    if len(descents) > 1:
        return -1
    k = (descents[0] + 1) % n
    rotated = lst[k:] + lst[:k]
    return k if rotated == sorted(lst) else -1

