def is_valid_css_rgb_string(s):
    if not (s.startswith('rgb(') and s.endswith(')')):
        return False
    inner = s[4:-1]
    parts = inner.split(', ')
    if len(parts) != 3:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        if int(part) > 255:
            return False
    return True

def prime_factors(n):
    def smallest_factor(m):
        if m % 2 == 0:
            return 2
        f = 3
        while f * f <= m:
            if m % f == 0:
                return f
            f += 2
        return m
    factors = []
    remaining = n
    while remaining > 1:
        f = smallest_factor(remaining)
        factors.append(f)
        remaining //= f
    return factors

