def local_to_utc(hh, mm, utc_offset_minutes):
    total = hh * 60 + mm - utc_offset_minutes
    day_delta = 0
    while total < 0:
        total += 1440
        day_delta -= 1
    while total >= 1440:
        total -= 1440
        day_delta += 1
    return (total // 60, total % 60, day_delta)

